import json
import re

payload = json.loads(r"""$exec""")

if not isinstance(payload, dict):
    raise ValueError("Le payload doit etre un objet JSON")

af = payload.get("_source") or payload.get("all_fields") or payload
data = af.get("data") or {}
rule = af.get("rule") or {}
agent = af.get("agent") or {}
agent_os = agent.get("os") or {}

def clean(value):
    if value is None:
        return ""
    text = str(value).strip()
    return "" if text.upper() == "NULL" else text

def pick(*values):
    for value in values:
        text = clean(value)
        if text:
            return text
    return ""


def classify_os(os_name):
    hint = clean(os_name).lower()
    if not hint:
        return ""
    if "win" in hint:
        return "windows"
    if any(k in hint for k in ("linux", "ubuntu", "debian", "centos", "redhat", "alpine", "rhel")):
        return "linux"
    return ""

text = pick(af.get("full_log"), payload.get("text"))

match = re.search(
    r"\{([A-Za-z0-9]+)\}\s+"
    r"(\d{1,3}(?:\.\d{1,3}){3})(?::(\d+))?"
    r"\s*->\s*"
    r"(\d{1,3}(?:\.\d{1,3}){3})(?::(\d+))?",
    text,
)

result = {
    "alert_id": pick(af.get("id"), payload.get("id")),
    "timestamp": pick(af.get("timestamp"), payload.get("timestamp")),
    "rule_id": pick(rule.get("id"), payload.get("rule_id")),
    "rule_description": pick(
        rule.get("description"), payload.get("title")
    ),
    "agent_name": clean(agent.get("name")),
    "agent_os_name": pick(
        agent_os.get("name"),
        af.get("agent_os"),
        af.get("os"),
        data.get("os"),
    ),
    "sensor": clean(af.get("location")),
    "sid": clean(data.get("suricata_sid")),
    "src_ip": pick(
        data.get("srcip"), match.group(2) if match else None
    ),
    "dst_ip": pick(
        data.get("dstip"), match.group(4) if match else None
    ),
    "protocol": pick(
        data.get("protocol"),
        data.get("proto"),
        match.group(1) if match else None,
    ).upper(),
    "dst_port": pick(
        data.get("dstport"), match.group(5) if match else None
    ),
}

result["target_os"] = classify_os(result.get("agent_os_name"))

if not result["alert_id"] or not result["rule_id"]:
    raise ValueError("Identifiant evenement ou regle Wazuh absent")

result["valid"] = True

print(json.dumps(result))

import json

identity = json.loads(r"""$build_dedup_identity.message""")
response = json.loads(r"""$check_duplicate_alert""")

if str(response.get("status")) != "200":
    raise ValueError(
        "Recherche TheHive en erreur : " + str(response.get("status"))
    )

alerts = response.get("body")
if isinstance(alerts, str):
    alerts = json.loads(alerts)

if not isinstance(alerts, list):
    raise ValueError("Liste d'alertes TheHive attendue")

def fields(alert):
    values = alert.get("customFields") or []
    if not isinstance(values, list):
        raise ValueError(
            "Format customFields inattendu : liste name/value attendue"
        )
    return values

exact = [
    alert for alert in alerts
    if alert.get("sourceRef") == identity["source_ref"]
    or identity["event_tag"] in (alert.get("tags") or [])
]

if len(exact) > 1:
    raise ValueError("Plusieurs alertes contiennent le meme evenement")

if exact:
    result = {
        "action": "skip",
        "target_alert_id": exact[0]["_id"],
    }

else:
    active = []

    for alert in alerts:
        if not identity["group_tag"]:
            continue
        if identity["group_tag"] not in (alert.get("tags") or []):
            continue

        last_seen = next((
            field["value"]
            for field in fields(alert)
            if field.get("name") == "wazuh-last-seen"
        ), None)

        if type(last_seen) is not int:
            raise ValueError("wazuh-last-seen absent ou invalide")

        if last_seen > identity["received_ms"]:
            raise ValueError("Date du groupe situee dans le futur")

        if last_seen >= identity["cutoff_ms"]:
            active.append(alert)

    if len(active) > 1:
        raise ValueError("Plusieurs groupes actifs pour cette empreinte")

    target = active[0] if active else None

    custom_fields = [
        {"name": field["name"], "value": field["value"]}
        for field in fields(target)
        if field["name"] != "wazuh-last-seen"
    ] if target else []

    custom_fields.append({
        "name": "wazuh-last-seen",
        "value": identity["received_ms"],
    })

    tags = [identity["event_tag"]]
    if identity["group_tag"]:
        tags.append(identity["group_tag"])

    result = {
        "action": "update" if target else "create",
        "target_alert_id": target["_id"] if target else None,
        "source_ref": identity["source_ref"],
        "metadata": {
            "tags": tags,
            "customFields": custom_fields,
        },
    }

print(json.dumps(result))

import hashlib
import ipaddress
import json
import time

INSTANCE = "wazuh-lab"

event = json.loads(r"""$normalize_event.message""")

if event.get("valid") is not True:
    raise ValueError("Evenement normalise invalide")

def digest(value):
    text = json.dumps(value, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(text.encode("utf-8")).hexdigest()

protocol = event["protocol"]

identity = {
    "version": 1,
    "instance": INSTANCE,
    "sensor": event["sensor"],
    "rule_id": event["rule_id"],
    "sid": event["sid"],
    "src_ip": event["src_ip"],
    "dst_ip": event["dst_ip"],
    "protocol": protocol,
    "dst_port": "",
}

groupable = bool(
    identity["sensor"]
    and identity["sid"]
    and identity["src_ip"]
    and identity["dst_ip"]
    and protocol in ("TCP", "UDP", "ICMP", "ICMPV6")
)

if groupable:
    identity["src_ip"] = str(ipaddress.ip_address(identity["src_ip"]))
    identity["dst_ip"] = str(ipaddress.ip_address(identity["dst_ip"]))

if protocol in ("TCP", "UDP"):
    port = event["dst_port"]
    if not port:
        groupable = False
    else:
        number = int(port)
        if not 0 <= number <= 65535:
            raise ValueError("Port destination invalide")
        identity["dst_port"] = str(number)

source_ref = f"wazuh:{INSTANCE}:{event['alert_id']}"
event_tag = "wazuh-event:" + digest([INSTANCE, event["alert_id"]])
group_tag = (
    "wazuh-group:v1:" + digest(identity)
    if groupable else None
)

received_ms = time.time_ns() // 1_000_000

alternatives = [
    {"_eq": {"_field": "sourceRef", "_value": source_ref}},
    {"_eq": {"_field": "tags", "_value": event_tag}},
]

if group_tag:
    alternatives.append({
        "_eq": {"_field": "tags", "_value": group_tag}
    })

query = {
    "query": [
        {"_name": "listAlert"},
        {
            "_name": "filter",
            "_and": [
                {"_eq": {"_field": "source", "_value": "wazuh"}},
                {"_eq": {"_field": "type", "_value": "wazuh"}},
                {"_or": alternatives},
            ],
        },
    ]
}

print(json.dumps({
    "groupable": groupable,
    "identity": identity,
    "source_ref": source_ref,
    "event_tag": event_tag,
    "group_tag": group_tag,
    "received_ms": received_ms,
    "cutoff_ms": received_ms - 600000,
    "query_body": json.dumps(query),
}))

